closure=read('CODE_CLOSURE.json');assert closure['status']=='PASS' and not closure['unbound']
for pin in read('CURRENT_EXECUTABLE_REVIEW_PACKET.json')['code']:assert sha(R/pin['path'])==pin['sha256']
assert a['fileSha256']==read('REAL_EXECUTION.json')['protectedDatabase']['before']['sha256']
